import { Component } from '@angular/core';

@Component({
  selector: 'app-root', // or 'app-nav' if using a separate component
  templateUrl: './app.component.html', // or './nav.component.html'
  styleUrls: ['./app.component.css'] // or './nav.component.css'
})
export class NavMenuComponent {
  isExpanded = false;

  toggle() {
    this.isExpanded = !this.isExpanded;
  }

  toggleLanguage() {
    const langToggle = document.getElementById('languageToggle') as HTMLInputElement;
    const isMacedonian = langToggle.checked;
    // Placeholder for language switch (implement with ngx-translate)
    console.log('Language toggled to:', isMacedonian ? 'Macedonian' : 'English');
    // Example with ngx-translate:
    // import { TranslateService } from '@ngx-translate/core';
    // constructor(private translate: TranslateService) {}
    // toggleLanguage() {
    //   const lang = this.langToggle.checked ? 'mk' : 'en';
    //   this.translate.use(lang);
    // }
  }

  openLoginModal() {
    document.getElementById('loginModal')?.classList.remove('hidden');
  }
}
